import { searchTools } from './search.js';
import { recallTools } from './recall.js';
import { logger } from '../utils/logger.js';
import { APIClient } from '../api/client.js';

// 创建简化的schema对象，符合MCP协议要求
const createMethodSchema = (method) => ({
  shape: {
    method: { value: method }
  },
  parse: (data) => data // 简单的解析函数
});

const ListToolsRequestSchema = createMethodSchema('tools/list');
const CallToolRequestSchema = createMethodSchema('tools/call');

export async function registerTools(server) {
  logger.info('Registering MCP tools...');
  
  // 为每个工具创建请求处理器
  const allTools = [...searchTools, ...recallTools];
  
  // 创建工具映射
  const toolMap = {};
  for (const tool of allTools) {
    toolMap[tool.name] = tool;
  }
  
  // 注册 tools/list 处理器
  server.setRequestHandler(
    ListToolsRequestSchema,
    async (request) => {
      return {
        tools: allTools.map(tool => ({
          name: tool.name,
          description: tool.description,
          inputSchema: tool.parameters
        }))
      };
    }
  );
  
  // 注册 tools/call 处理器
  server.setRequestHandler(
    CallToolRequestSchema,
    async (request) => {
      const toolName = request.params.name;
      const tool = toolMap[toolName];
      
      if (!tool) {
        throw {
          code: -32602,
          message: `Tool not found: ${toolName}`
        };
      }
      
      logger.info(`Calling tool: ${toolName}`);
      
      try {
        const result = await tool.handler(request.params.arguments || {}, { api: new APIClient() });
        return result;
      } catch (error) {
        logger.error(`Tool ${toolName} execution failed:`, error);
        throw {
          code: -32603,
          message: `Tool execution failed: ${error.message}`
        };
      }
    }
  );
  
  logger.info(`Total tools registered: ${allTools.length}`);
}